}
local function loadMod(name)
  local fn = assert(loadstring(SOURCES[name], "@" .. name))
  return fn()
end
script.Parent.RumbleConfig = loadMod("RumbleConfig")
script.Parent.BrainrotCatalog = loadMod("BrainrotCatalog")
script.Parent.MoneyFormat = loadMod("MoneyFormat")
script.Parent.MissionCatalog = loadMod("MissionCatalog")
local GS = loadMod("GameState")
local RC = script.Parent.RumbleConfig
local Catalog = script.Parent.BrainrotCatalog

local failures = 0
local function check(name, cond, got)
  if cond then
    print("PASS  " .. name)
  else
    failures = failures + 1
    print("FAIL  " .. name .. "  (got " .. tostring(got) .. ")")
  end
end

-- 1. Fresh player defaults.
local s = GS.NewPlayer()
check("fresh Rebirths=0", s.Rebirths == 0, s.Rebirths)
check("fresh Multiplier=1", s.Multiplier == 1, s.Multiplier)
check("fresh ComboCount=0", s.ComboCount == 0, s.ComboCount)
check("fresh RebirthMissionBase=0", s.RebirthMissionBase == 0, s.RebirthMissionBase)
check("fresh cash=StartCash", s.Cash == RC.StartCash, s.Cash)

-- 2. Rebirth is gated at the start.
local ok, hint = GS.CanRebirth(s)
check("rebirth NOT ready at start", ok == false, ok)
check("rebirth hint names $100,000", hint == "need $100,000", hint)

-- 3. Combo: a brainrot bought on a streak earns at the tier while the
-- stamp lasts, then reverts to its normal rate.
local now = os.time()
GS.AddBrainrot(s, "ayam-geprek", "Normal", 3, now + 60) -- combo x3, 60s
check("combo income is 3x while stamped", GS.BaseIncome(s, now) == 2 * 3, GS.BaseIncome(s, now))
check("combo income reverts after stamp", GS.BaseIncome(s, now + 61) == 2, GS.BaseIncome(s, now + 61))
GS.AddBrainrot(s, "sendal", "Normal") -- plain add, no combo
check("plain brainrot earns normal rate", GS.BaseIncome(s, now) == 2 * 3 + 1, GS.BaseIncome(s, now))

-- 4. Earn $100,000 lifetime -> rebirth unlocks; apply it.
GS.AddCash(s, 100000)
check("TotalEarned tracks lifetime", s.TotalEarned == 100000, s.TotalEarned)
ok, _ = GS.CanRebirth(s)
check("rebirth ready at $100K lifetime", ok == true, ok)
-- Mark a mission done and give the player upgrades, so we can see what
-- survives the wipe.
s.MissionsDone["first-buy"] = true
s.Upgrades.Boots = 2
s.Discovered["ayam-geprek"] = true
GS.ApplyRebirth(s)
check("rebirth: Rebirths=1", s.Rebirths == 1, s.Rebirths)
check("rebirth: Multiplier=1.5 (+50%)", s.Multiplier == 1.5, s.Multiplier)
check("rebirth: cash reset to StartCash", s.Cash == RC.StartCash, s.Cash)
check("rebirth: brainrots wiped", #s.Brainrots == 0, #s.Brainrots)
check("rebirth: missions wiped", next(s.MissionsDone) == nil, "missions remain")
check("rebirth: ChainBonus cleared", s.ChainBonus == false, s.ChainBonus)
check("rebirth: combo cleared", s.ComboCount == 0 and s.ComboUntil == 0, s.ComboCount)
check("rebirth: upgrades SURVIVE", s.Upgrades.Boots == 2, s.Upgrades.Boots)
check("rebirth: Index SURVIVES", s.Discovered["ayam-geprek"] == true, "discovered lost")
check("rebirth: lifetime earnings SURVIVE", s.TotalEarned == 100000, s.TotalEarned)
check("rebirth: mission base re-armed", s.RebirthMissionBase == 1, s.RebirthMissionBase)

-- 5. The rebirth mission needs ANOTHER rebirth after the wipe.
local MC = script.Parent.MissionCatalog
local rebirthMission = nil
for _, m in ipairs(MC.Missions) do
	if m.Id == "rebirth-once" then rebirthMission = m end
end
check("rebirth mission found", rebirthMission ~= nil, "nil")
check("rebirth mission NOT done right after rebirth", rebirthMission.Check(s) == 0, rebirthMission.Check(s))
s.Rebirths = 2
check("rebirth mission done after 2nd rebirth", rebirthMission.Check(s) == 1, rebirthMission.Check(s))
s.Rebirths = 1 -- restore

-- 6. Multiplier caps at x5 (8 rebirths) and rebirth locks then.
s.Rebirths = 7
s.RebirthMissionBase = 7
GS.ApplyRebirth(s) -- 8th rebirth
check("8 rebirths -> Multiplier=5 (cap)", s.Multiplier == 5, s.Multiplier)
ok, hint = GS.CanRebirth(s)
check("rebirth locked at cap", ok == false and hint == "MAXED x5", hint)

-- 7. Snapshot carries the new fields without error.
local snap = GS.Snapshot(s, os.time())
check("snapshot Rebirths", snap.Rebirths == 8, snap.Rebirths)
check("snapshot Multiplier=5", snap.Multiplier == 5, snap.Multiplier)
check("snapshot RebirthReady=false at cap", snap.RebirthReady == false, snap.RebirthReady)
check("snapshot ComboCount present", snap.ComboCount == 0, snap.ComboCount)
check("snapshot ComboLeft present", snap.ComboLeft == 0, snap.ComboLeft)
check("snapshot RebirthHint present", snap.RebirthHint == "MAXED x5", snap.RebirthHint)

-- 8. Mission-chain path also unlocks rebirth (all 10 missions done).
local s2 = GS.NewPlayer()
for _, m in ipairs(MC.Missions) do
	s2.MissionsDone[m.Id] = true
end
ok, _ = GS.CanRebirth(s2)
check("rebirth ready via all-10-missions", ok == true, ok)

-- 9. Sell price is 70% of cost (mutation NOT paid) — the exploit is gone.
local def = Catalog.Get("kucing-dewa") -- Secret, Cost 400000, rate 5000
local sellPrice = math.floor(def.Cost * RC.SellFraction)
check("sell pays 70% of cost only", sellPrice == 280000, sellPrice)

print(failures == 0 and "ALL TESTS PASSED" or ("FAILURES: " .. failures))
-- (No os.exit: the Luau CLI does not expose it; the line above is the verdict.)
